#[path="../../../../../../../../../../../../../../🧰️framework/🔨️modules/🌱️value/📽️projection/👁️post/🧪️testing/🦀️.rs"]mod post_fixture;
use post_fixture::PostFixture;
use super::*;
use semio_framework_value::{retirement::RetireOwned,retained_clone::RetainedCloneSource};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{match RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096}){Ok((owner,_))=>owner,Err((error,_,_))=>panic!("{error}")}}
fn close_source<T:RetireOwned+Sync+'static>(owner:&mut RetainedCloneSource<T>){for _ in 0..1000000{if owner.terminal_is_empty(){return}let d=RetirementDemand{copy_bytes:owner.next_close_copy_byte_demand().unwrap(),capacity_bytes:owner.next_close_capacity_byte_demand(65536).unwrap(),release_bytes:owner.next_close_release_byte_demand().unwrap(),depth:owner.next_close_depth_demand().unwrap()};owner.close_step(grant(d)).unwrap();}panic!("source retirement stalled")}
fn close(owner:&mut protocol::RetainedDiffOwner<LayoutSnapshot,LayoutDiff>){owner.begin_close();for _ in 0..1000000{if owner.terminal_is_empty(){return}let d=owner.close_demand(65536).unwrap();assert_eq!(owner.close_step(Default::default()).unwrap().progress(),Default::default());let step=owner.close_step(grant(d)).unwrap();assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){assert!(owner.terminal_is_empty(),"child completion cannot settle the original parent")}}panic!("Layout retained original close stalled")}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
#[test]
fn production_layout_retained_diff_matches_neutral_rfc6902_witnesses_without_post_clone(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/🧮️diff-algebra/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){let original:LayoutSnapshot=decode(&case["before"]);let expected:LayoutSnapshot=decode(&case["after"]);let event:LayoutDiff=decode(&case["diff"]);let mut post=PostFixture::new(original.clone());let untouched=post.stories.iter().map(|row|(row.id.clone(),row.content.as_ptr())).collect::<Vec<_>>();let mut base=source(original.clone());let mut diff=source(event.clone());let(mut owner,_)=protocol::begin_retained_diff::<LayoutSnapshot,LayoutDiff>(grant(protocol::retained_diff_birth_demand::<LayoutSnapshot,LayoutDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);let mut admitted=false;for _ in 0..1000000{let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),65536).unwrap();assert_eq!(protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),65536,Default::default(),&mut receiving).unwrap().progress(),Default::default());let step=protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),65536,grant(d),&mut receiving).unwrap();assert!(step.progress().fits(grant(d)));assert_eq!(post,original,"{}: read-only admission",case["name"]);if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)){admitted=true;break}}assert!(admitted,"{}",case["name"]);post.mutable_read();let mut committed=false;for _ in 0..1000000{let d=owner.commit_demand(diff.borrow(),base.borrow(),post.borrow(),65536).unwrap();assert_eq!(protocol::commit_retained_diff(&mut owner,diff.borrow(),base.borrow(),&mut post,Default::default()).unwrap().progress(),Default::default());let step=protocol::commit_retained_diff(&mut owner,diff.borrow(),base.borrow(),&mut post,grant(d)).unwrap();assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){committed=true;break}}assert!(committed);assert_eq!(post,expected,"{}",case["name"]);if event.stories.is_none(){for(id,pointer)in untouched{assert_eq!(post.stories.iter().find(|row|row.id==id).unwrap().content.as_ptr(),pointer)}}assert_eq!(base.borrow().get(),&original);assert_eq!(diff.borrow().get(),&event);close(&mut owner);close_source(&mut diff);close_source(&mut base);let mut output=source(post.into_inner());close_source(&mut output)}}
#[test]
fn production_layout_retained_preflight_cancellation_closes_all_originals(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/🧮️diff-algebra/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){for cut in[0,1,8,32,128]{let original:LayoutSnapshot=decode(&case["before"]);let event:LayoutDiff=decode(&case["diff"]);let mut base=source(original.clone());let mut diff=source(event);let post=PostFixture::new(original.clone());let(mut owner,_)=protocol::begin_retained_diff::<LayoutSnapshot,LayoutDiff>(grant(protocol::retained_diff_birth_demand::<LayoutSnapshot,LayoutDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);for _ in 0..cut{let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),65536).unwrap();let step=protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),65536,grant(d),&mut receiving).unwrap();if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)|protocol::RetainedDiffPreflightStep::Refused(..)){break}}assert_eq!(base.borrow().get(),&original);close(&mut owner);drop(post);close_source(&mut diff);close_source(&mut base)}}}
